pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 val, uint256 blockNum) public {
        vm.assume(val > 0);
        vm.assume(blockNum > 0);
        vm.assume(blockNum % 15 != 0);
        vm.deal(address(this), val);
        vm.roll(blockNum);
        vm.warp(1);
        (bool ok,) = address(c).call{value: val}("");
        if (ok) {
            assertTrue(address(c).balance == 0 || val == 10 ether);
        }
    }
}
